import {qualify,csvCell} from './scoring.mjs';
const $=s=>document.querySelector(s),key='leadroom-v1';
const samples=[{id:'1',seller:'Alex Morgan',address:'42 Maple St, Tampa, FL',motivation:'high',timeline:'soon',condition:'repairs',asking:185000,value:240000},{id:'2',seller:'Jamie Parker',address:'18 Oak Lane, Austin, TX',motivation:'medium',timeline:'quarter',condition:'cosmetic',asking:295000,value:310000},{id:'3',seller:'Taylor Reed',address:'76 Cedar Ave, Phoenix, AZ',motivation:'high',timeline:'soon',condition:'cosmetic',asking:225000,value:250000},{id:'4',seller:'Jordan Ellis',address:'9 Willow Dr, Orlando, FL',motivation:'low',timeline:'later',condition:'ready',asking:340000,value:310000}];
let leads;try{const saved=JSON.parse(localStorage.getItem(key));leads=Array.isArray(saved)?saved.filter(x=>{try{qualify(x);return typeof x.seller==='string'&&typeof x.address==='string'&&typeof x.id==='string'}catch{return false}}):structuredClone(samples)}catch{leads=structuredClone(samples)}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function persist(){try{localStorage.setItem(key,JSON.stringify(leads))}catch{toast('Storage is unavailable. Changes last only while this page is open.')}}
function render(){const ranked=leads.map(l=>({...l,...qualify(l)})).sort((a,b)=>b.score-a.score);$('#total').textContent=leads.length;$('#count').textContent=leads.length;$('#hot').textContent=ranked.filter(l=>l.tier==='Hot').length;$('#average').textContent=leads.length?Math.round(ranked.reduce((s,l)=>s+l.score,0)/leads.length):0;$('#volume').textContent=money(leads.reduce((s,l)=>s+l.asking,0));const query=$('#search').value.toLowerCase();const visible=ranked.filter(l=>(l.seller+' '+l.address).toLowerCase().includes(query)&&($('#filter').value==='All'||$('#filter').value===l.tier));$('#rows').innerHTML=visible.length?visible.map(l=>`<tr><td><strong>${esc(l.seller)}</strong><small>${esc(l.address)}</small></td><td><span class="signal ${l.tier}"><b>${l.score}</b> ${l.tier}</span></td><td>${money(l.asking)}</td><td><button class="delete" data-id="${esc(l.id)}" aria-label="Delete ${esc(l.seller)}">×</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty">No leads here yet. Try another search or qualify a new lead.</td></tr>'}
$('#search').addEventListener('input',render);$('#filter').addEventListener('change',render);
$('#rows').addEventListener('click',e=>{const button=e.target.closest('button[data-id]');if(!button)return;leads=leads.filter(l=>l.id!==button.dataset.id);persist();render();toast('Lead removed from this browser.')});
$('#newLead').onclick=()=>{$('#qualifier').scrollIntoView({behavior:'smooth'});$('#leadForm [name=seller]').focus({preventScroll:true})};
$('#leadForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.seller=data.seller.trim();data.address=data.address.trim();if(!data.seller||!data.address){toast('Add a seller name and address.');return}data.asking=Number(data.asking);data.value=Number(data.value);let result;try{result=qualify(data)}catch(error){toast(error.message);return}const box=$('#result');box.hidden=false;box.innerHTML=`<h3>${result.score}/100 <span class="signal ${result.tier}">${result.tier} priority</span></h3><div class="breakdown">${result.breakdown.map(([label,points,max])=>`<div class="break-row"><span>${label}</span><div class="track"><span style="width:${points/max*100}%"></span></div><span>${points}/${max}</span></div>`).join('')}</div><p>${result.next}</p><p>Illustrative prioritization only. Estimated value is your input, not an appraisal.</p><button id="saveLead" class="primary full">Save to pipeline <span>＋</span></button>`;$('#saveLead').onclick=()=>{leads.push({...data,id:globalThis.crypto?.randomUUID?.() ?? `lead-${Date.now()}-${Math.random().toString(36).slice(2)}`});persist();render();$('#saveLead').disabled=true;$('#saveLead').textContent='✓ Saved to pipeline';toast(`${data.seller} added to your pipeline.`)}};
$('#leadForm').addEventListener('input',()=>{$('#result').hidden=true});
$('#reset').onclick=()=>{if(!confirm('Replace this browser’s saved leads with the fictional demo data?'))return;leads=structuredClone(samples);persist();$('#search').value='';$('#filter').value='All';$('#result').hidden=true;render();toast('Demo pipeline restored.')};
$('#export').onclick=()=>{const rows=[['Seller','Address','Asking price','Estimated value','Score','Priority'],...leads.map(l=>[l.seller,l.address,l.asking,l.value,qualify(l).score,qualify(l).tier])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='leadroom-pipeline.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Pipeline exported to CSV.')};render();
